const enc = new TextEncoder();

function b64url(bytes) {
  return btoa(String.fromCharCode(...new Uint8Array(bytes)))
    .replace(/\+/g,"-").replace(/\//g,"_").replace(/=+$/,"");
}
function fromB64url(s) {
  s=s.replace(/-/g,"+").replace(/_/g,"/");
  while(s.length%4)s+="=";
  return Uint8Array.from(atob(s),c=>c.charCodeAt(0));
}
async function hmac(secret, message) {
  const key = await crypto.subtle.importKey(
    "raw", enc.encode(secret), {name:"HMAC",hash:"SHA-256"}, false, ["sign"]
  );
  return new Uint8Array(await crypto.subtle.sign("HMAC", key, enc.encode(message)));
}
async function signPayload(secret, obj, purpose) {
  const payload = b64url(enc.encode(JSON.stringify(obj)));
  const sig = b64url(await hmac(secret, `${purpose}.${payload}`));
  return `${payload}.${sig}`;
}
async function verifyPayload(secret, token, purpose) {
  try {
    const [payload,sig] = String(token||"").split(".");
    if(!payload||!sig)return null;
    const expected = b64url(await hmac(secret, `${purpose}.${payload}`));
    if(expected!==sig)return null;
    const obj = JSON.parse(new TextDecoder().decode(fromB64url(payload)));
    return obj;
  } catch { return null; }
}
function normEmail(v){return String(v||"").trim().toLowerCase()}
async function sha256(v){
  return Array.from(new Uint8Array(await crypto.subtle.digest("SHA-256",enc.encode(v))))
    .map(x=>x.toString(16).padStart(2,"0")).join("");
}
function validEmail(v){
  const s=normEmail(v);
  return s.length<=254 && /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(s);
}
function cleanOrderId(v){
  const s=String(v||"").trim();
  return /^[A-Za-z0-9._-]{1,80}$/.test(s)?s:"";
}
function cleanDeviceId(v){
  const s=String(v||"").trim();
  return /^[A-Za-z0-9-]{16,80}$/.test(s)?s:"";
}
async function rateLimit(env,req,bucket,limit,windowSec){
  const ip=req.headers.get("cf-connecting-ip")||"unknown";
  const key=`frontshelf:rl:${bucket}:${await sha256(ip)}`;
  const count=Number(await redisPost(env,["INCR",key]))||0;
  if(count===1)await redisPost(env,["EXPIRE",key,String(windowSec)]);
  return {allowed:count<=limit,remaining:Math.max(0,limit-count)};
}
async function verifyLicenseCode(env,email,code){
  if(!validEmail(email) || typeof code!=="string" || code.length<20 || code.length>2048)return null;
  const lic=await verifyPayload(env.LICENSE_SIGNING_SECRET,code,"license");
  if(!lic || normEmail(lic.email)!==normEmail(email))return null;
  return lic;
}

const BASE_SECURITY_HEADERS={
  "x-content-type-options":"nosniff",
  "x-frame-options":"DENY",
  "referrer-policy":"no-referrer",
  "permissions-policy":"camera=(), microphone=(), geolocation=(), payment=()",
  "cross-origin-opener-policy":"same-origin",
  "cross-origin-resource-policy":"same-origin"
};
function json(data,status=200,headers={}){
  return new Response(JSON.stringify(data),{status,headers:{
    "content-type":"application/json;charset=utf-8",
    "cache-control":"no-store",
    ...BASE_SECURITY_HEADERS,
    ...headers
  }})
}
function html(body,status=200,headers={}){
  return new Response(body,{status,headers:{
    "content-type":"text/html;charset=utf-8",
    "cache-control":"no-store",
    "content-security-policy":"default-src 'self'; script-src 'self' 'unsafe-inline'; style-src 'self' 'unsafe-inline'; img-src 'self' data: blob:; connect-src 'self'; font-src 'self' data:; frame-ancestors 'none'; base-uri 'none'; form-action 'self'",
    ...BASE_SECURITY_HEADERS,
    ...headers
  }})
}
function cookie(req,name){
  const raw=req.headers.get("cookie")||"";
  const m=raw.match(new RegExp(`(?:^|; )${name}=([^;]*)`));
  return m?decodeURIComponent(m[1]):"";
}
function sessionCookie(token){
  return `frontshelf_session=${encodeURIComponent(token)}; Path=/; HttpOnly; Secure; SameSite=Strict; Max-Age=2592000`;
}
async function redis(env,args){
  const url = env.UPSTASH_REDIS_REST_URL;
  const token = env.UPSTASH_REDIS_REST_TOKEN;
  if(!url||!token)throw new Error("UPSTASH_NOT_CONFIGURED");
  const path=args.map(v=>encodeURIComponent(String(v))).join("/");
  const r=await fetch(`${url}/${path}`,{headers:{Authorization:`Bearer ${token}`}});
  const j=await r.json();
  if(!r.ok||j.error)throw new Error(j.error||"Upstash request failed");
  return j.result;
}
async function redisPost(env,args){
  const url=env.UPSTASH_REDIS_REST_URL;
  const token=env.UPSTASH_REDIS_REST_TOKEN;
  if(!url||!token)throw new Error("UPSTASH_NOT_CONFIGURED");
  const r=await fetch(url,{
    method:"POST",
    headers:{Authorization:`Bearer ${token}`,"content-type":"application/json"},
    body:JSON.stringify(args)
  });
  const j=await r.json();
  if(!r.ok||j.error)throw new Error(j.error||"Upstash request failed");
  return j.result;
}
async function syncCryptoKey(env){
  const raw=await crypto.subtle.digest("SHA-256",enc.encode(`frontshelf-sync-v1|${env.LICENSE_SIGNING_SECRET}`));
  return crypto.subtle.importKey("raw",raw,{name:"AES-GCM"},false,["encrypt","decrypt"]);
}
async function encryptSyncPayload(env,obj){
  const key=await syncCryptoKey(env),iv=crypto.getRandomValues(new Uint8Array(12));
  const plain=enc.encode(JSON.stringify(obj));
  const cipher=new Uint8Array(await crypto.subtle.encrypt({name:"AES-GCM",iv},key,plain));
  return `v1.${b64url(iv)}.${b64url(cipher)}`;
}
async function decryptSyncPayload(env,value){
  try{
    const [v,iv64,cipher64]=String(value||"").split(".");
    if(v!=="v1"||!iv64||!cipher64)return null;
    const key=await syncCryptoKey(env);
    const plain=await crypto.subtle.decrypt({name:"AES-GCM",iv:fromB64url(iv64)},key,fromB64url(cipher64));
    return JSON.parse(new TextDecoder().decode(plain));
  }catch{return null}
}
async function syncDataKey(session){
  return `frontshelf:data:${await sha256(`${session.email}|${session.orderId||""}`)}`;
}

function stdBase64(bytes){return btoa(String.fromCharCode(...new Uint8Array(bytes)))}
function decodeStdBase64(s){return Uint8Array.from(atob(String(s||"")),c=>c.charCodeAt(0))}
async function hmacWithBytes(keyBytes,message){
  const key=await crypto.subtle.importKey("raw",keyBytes,{name:"HMAC",hash:"SHA-256"},false,["sign"]);
  return new Uint8Array(await crypto.subtle.sign("HMAC",key,enc.encode(message)));
}
function timingSafeStringEqual(a,b){
  a=String(a||"");b=String(b||"");
  if(a.length!==b.length)return false;
  let x=0;for(let i=0;i<a.length;i++)x|=a.charCodeAt(i)^b.charCodeAt(i);
  return x===0;
}
async function verifyEtsyWebhook(req,env,rawBody){
  const id=req.headers.get("webhook-id")||"",ts=req.headers.get("webhook-timestamp")||"",sigHeader=req.headers.get("webhook-signature")||"";
  if(!id||!ts||!sigHeader||!env.ETSY_WEBHOOK_SECRET)return {ok:false,error:"Missing Etsy webhook signature data."};
  const timestamp=Number(ts),now=Math.floor(Date.now()/1000);
  if(!Number.isFinite(timestamp)||Math.abs(now-timestamp)>300)return {ok:false,error:"Stale Etsy webhook timestamp."};
  let secret=String(env.ETSY_WEBHOOK_SECRET); if(secret.startsWith("whsec_"))secret=secret.slice(6);
  let keyBytes; try{keyBytes=decodeStdBase64(secret)}catch{return {ok:false,error:"Invalid Etsy webhook secret."}}
  const expected=stdBase64(await hmacWithBytes(keyBytes,`${id}.${ts}.${rawBody}`));
  const candidates=sigHeader.split(/\s+/).flatMap(x=>x.split(",")).map(x=>x.trim()).filter(Boolean);
  const match=candidates.some(x=>timingSafeStringEqual(x,expected)||timingSafeStringEqual(x.replace(/^v\d+=?/i,""),expected));
  return match?{ok:true,id,timestamp}:{ok:false,error:"Invalid Etsy webhook signature."};
}
function etsyApiKey(env){
  if(!env.ETSY_KEYSTRING||!env.ETSY_SHARED_SECRET)throw new Error("ETSY_APP_NOT_CONFIGURED");
  return `${env.ETSY_KEYSTRING}:${env.ETSY_SHARED_SECRET}`;
}
function etsyRedirectUri(req){return new URL("/api/etsy/oauth/callback",req.url).toString()}
async function randomB64Url(bytes=32){return b64url(crypto.getRandomValues(new Uint8Array(bytes)))}
async function pkceChallenge(verifier){
  return b64url(new Uint8Array(await crypto.subtle.digest("SHA-256",enc.encode(verifier))));
}
async function storeEtsyAuth(env,obj){
  await redisPost(env,["SET","frontshelf:etsy:auth",await encryptSyncPayload(env,obj)]);
}
async function loadEtsyAuth(env){
  const raw=await redisPost(env,["GET","frontshelf:etsy:auth"]);
  return raw?decryptSyncPayload(env,raw):null;
}
async function refreshEtsyAuth(env,auth){
  if(!auth?.refresh_token)throw new Error("ETSY_NOT_AUTHORIZED");
  const body=new URLSearchParams({grant_type:"refresh_token",client_id:String(env.ETSY_KEYSTRING||""),refresh_token:String(auth.refresh_token)});
  const r=await fetch("https://api.etsy.com/v3/public/oauth/token",{method:"POST",headers:{"content-type":"application/x-www-form-urlencoded"},body});
  const j=await r.json().catch(()=>({}));
  if(!r.ok||!j.access_token)throw new Error(`Etsy token refresh failed (${r.status}).`);
  const next={access_token:j.access_token,refresh_token:j.refresh_token||auth.refresh_token,scope:j.scope||auth.scope||"",expires_at:Date.now()+(Number(j.expires_in)||3600)*1000};
  await storeEtsyAuth(env,next); return next;
}
async function getEtsyAccessToken(env){
  let auth=await loadEtsyAuth(env); if(!auth)throw new Error("ETSY_NOT_AUTHORIZED");
  if(!auth.access_token||!auth.expires_at||Date.now()>Number(auth.expires_at)-120000)auth=await refreshEtsyAuth(env,auth);
  return auth.access_token;
}
async function fetchEtsyResource(env,url){
  const u=new URL(url);
  if(u.protocol!=="https:"||!["api.etsy.com","openapi.etsy.com"].includes(u.hostname))throw new Error("Unexpected Etsy resource URL.");
  let token=await getEtsyAccessToken(env);
  let r=await fetch(u.toString(),{headers:{"x-api-key":etsyApiKey(env),Authorization:`Bearer ${token}`}});
  if(r.status===401){token=(await refreshEtsyAuth(env,await loadEtsyAuth(env))).access_token;r=await fetch(u.toString(),{headers:{"x-api-key":etsyApiKey(env),Authorization:`Bearer ${token}`}})}
  const j=await r.json().catch(()=>({})); if(!r.ok)throw new Error(`Etsy receipt lookup failed (${r.status}).`); return j;
}
function htmlEscape(v){return String(v??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}
function receiptObject(x){
  if(x?.receipt_id)return x;
  if(Array.isArray(x?.results)&&x.results[0])return x.results[0];
  if(x?.receipt?.receipt_id)return x.receipt;
  return x||{};
}
function receiptBuyerEmail(r){return normEmail(r?.buyer_email||r?.email||r?.buyer?.email||"")}
function receiptHasPlanner(r,listingId){
  if(!listingId)return true;
  const wanted=String(listingId),tx=Array.isArray(r?.transactions)?r.transactions:[];
  return tx.some(t=>String(t?.listing_id||t?.listing?.listing_id||t?.product_data?.listing_id||"")===wanted);
}
function cleanEtsyReceiptId(v){
  const s=String(v||"").trim();
  return /^[1-9]\d{0,19}$/.test(s)?s:"";
}
async function resolveEtsyShopId(env){
  const configured=String(env.ETSY_SHOP_ID||"").trim();
  if(/^[1-9]\d*$/.test(configured))return configured;

  const cached=String(await redisPost(env,["GET","frontshelf:etsy:shop-id"])||"").trim();
  if(/^[1-9]\d*$/.test(cached))return cached;

  // Etsy access tokens are returned as "<numeric_user_id>.<token>".
  // Use that owner user ID with Etsy's official getShopByOwnerUserId endpoint.
  const auth=await loadEtsyAuth(env);
  if(!auth?.access_token)throw new Error("ETSY_NOT_AUTHORIZED");
  const userId=String(auth.access_token).split(".")[0]||"";
  if(!/^[1-9]\d*$/.test(userId))throw new Error("ETSY_OWNER_USER_ID_NOT_FOUND");

  const r=await fetch(`https://openapi.etsy.com/v3/application/users/${encodeURIComponent(userId)}/shops`,{
    headers:{"x-api-key":etsyApiKey(env)}
  });
  const j=await r.json().catch(()=>({}));
  if(!r.ok)throw new Error(`Etsy shop lookup failed (${r.status}).`);

  const shopId=String(j?.shop_id||j?.results?.[0]?.shop_id||"").trim();
  if(!/^[1-9]\d*$/.test(shopId))throw new Error("ETSY_SHOP_NOT_FOUND");

  await redisPost(env,["SET","frontshelf:etsy:shop-id",shopId]);
  return shopId;
}

async function fetchEtsyPrivateJson(env,url){
  const u=new URL(url);
  if(u.protocol!=="https:"||!["api.etsy.com","openapi.etsy.com"].includes(u.hostname))
    throw new Error("Unexpected Etsy resource URL.");

  let token=await getEtsyAccessToken(env);
  let r=await fetch(u.toString(),{
    headers:{"x-api-key":etsyApiKey(env),Authorization:`Bearer ${token}`}
  });

  if(r.status===401){
    token=(await refreshEtsyAuth(env,await loadEtsyAuth(env))).access_token;
    r=await fetch(u.toString(),{
      headers:{"x-api-key":etsyApiKey(env),Authorization:`Bearer ${token}`}
    });
  }

  if(r.status===404)return null;

  const j=await r.json().catch(()=>({}));
  if(!r.ok)throw new Error(`Etsy API lookup failed (${r.status}).`);
  return j;
}

async function getEtsyReceipt(env,receiptId){
  const shopId=await resolveEtsyShopId(env);
  return fetchEtsyPrivateJson(
    env,
    `https://openapi.etsy.com/v3/application/shops/${shopId}/receipts/${encodeURIComponent(receiptId)}`
  );
}

async function getEtsyReceiptTransactions(env,receiptId){
  const shopId=await resolveEtsyShopId(env);
  const result=await fetchEtsyPrivateJson(
    env,
    `https://openapi.etsy.com/v3/application/shops/${shopId}/receipts/${encodeURIComponent(receiptId)}/transactions`
  );
  return Array.isArray(result?.results)?result.results:[];
}

async function verifyEtsyPurchase(env,email,receiptId){
  const receipt=await getEtsyReceipt(env,receiptId);
  if(!receipt)return {ok:false,error:"That Etsy order could not be verified."};
  if(String(receipt?.receipt_id||"")!==String(receiptId))
    return {ok:false,error:"That Etsy order could not be verified."};
  const receiptStatus = String(receipt?.status || "").toLowerCase();
if (!["paid", "completed"].includes(receiptStatus))
    return {ok:false,error:"That Etsy order is not marked as paid."};

  const buyerEmail=receiptBuyerEmail(receipt);
  if(!buyerEmail||buyerEmail!==normEmail(email))
    return {ok:false,error:"That email does not match the Etsy order."};

  if(env.ETSY_PLANNER_LISTING_ID){
    let tx=Array.isArray(receipt?.transactions)?receipt.transactions:[];
    if(!tx.length)tx=await getEtsyReceiptTransactions(env,receiptId);
    const wanted=String(env.ETSY_PLANNER_LISTING_ID);
    if(!tx.some(t=>String(t?.listing_id||t?.listing?.listing_id||t?.product_data?.listing_id||"")===wanted))
      return {ok:false,error:"That Etsy order does not contain The Front Shelf planner."};
  }

  return {ok:true,receipt};
}

function decodePlanner(){
  const bin=atob(PLANNER_B64);
  const bytes=Uint8Array.from(bin,c=>c.charCodeAt(0));
  return new TextDecoder().decode(bytes);
}
async function verifySession(req,env){
  const raw=cookie(req,"frontshelf_session");
  if(!raw)return null;
  const s=await verifyPayload(env.LICENSE_SIGNING_SECRET,raw,"session");
  if(!s||!s.email||!s.deviceId||!s.exp||Date.now()>s.exp)return null;
  const key=`frontshelf:devices:${await sha256(s.email)}`;
  const members=await redis(env,["smembers",key])||[];
  if(!members.includes(s.deviceId))return null;
  return s;
}
