const PLANNER_B64 = "";

export default {
  async fetch(req,env) {
    const url=new URL(req.url);
    try {
      const len=Number(req.headers.get("content-length")||0);
      if(len>1000000)return json({ok:false,error:"Request too large."},413);
      if(req.method==="OPTIONS")return new Response(null,{status:204,headers:BASE_SECURITY_HEADERS});
      if(url.pathname==="/health") return json({ok:true,service:"the-front-shelf-access",etsyConfigured:!!(env.ETSY_KEYSTRING&&env.ETSY_SHARED_SECRET&&env.ETSY_WEBHOOK_SECRET)});
      if(url.pathname==="/") return html(loginPage());
      if(url.pathname==="/admin") return html(adminPage());

      if(url.pathname==="/planner"){
        const s=await verifySession(req,env);
        if(!s)return Response.redirect(new URL("/",url),302);
        return html(decodePlanner());
      }

      if(url.pathname==="/api/etsy/oauth/start" && req.method==="POST"){
        const rl=await rateLimit(env,req,"etsy-oauth-start",6,600);
        if(!rl.allowed)return json({ok:false,error:"Too many attempts. Try again later."},429);
        const body=await req.json().catch(()=>({}));
        if(!env.ADMIN_SECRET||typeof body.adminSecret!=="string"||body.adminSecret!==env.ADMIN_SECRET)return json({ok:false,error:"Invalid admin secret."},401);
        if(!env.ETSY_KEYSTRING||!env.ETSY_SHARED_SECRET)return json({ok:false,error:"Etsy app credentials are not configured in Cloudflare."},503);
        const state=await randomB64Url(24),verifier=await randomB64Url(48),challenge=await pkceChallenge(verifier);
        await redisPost(env,["SET",`frontshelf:etsy:oauth:${state}`,verifier,"EX","600"]);
        const u=new URL("https://www.etsy.com/oauth/connect");
        u.searchParams.set("response_type","code");u.searchParams.set("redirect_uri",etsyRedirectUri(req));u.searchParams.set("scope","transactions_r");
        u.searchParams.set("client_id",String(env.ETSY_KEYSTRING));u.searchParams.set("state",state);u.searchParams.set("code_challenge",challenge);u.searchParams.set("code_challenge_method","S256");
        return json({ok:true,url:u.toString()});
      }

      if(url.pathname==="/api/etsy/oauth/callback" && req.method==="GET"){
        const state=String(url.searchParams.get("state")||""),code=String(url.searchParams.get("code")||"");
        if(!state||!code)return html("<h2>Etsy authorization failed.</h2><p>Missing authorization response.</p>",400);
        const verifier=await redisPost(env,["GET",`frontshelf:etsy:oauth:${state}`]);
        if(!verifier)return html("<h2>Etsy authorization expired.</h2><p>Return to /admin and connect Etsy again.</p>",400);
        await redisPost(env,["DEL",`frontshelf:etsy:oauth:${state}`]);
        const body=new URLSearchParams({grant_type:"authorization_code",client_id:String(env.ETSY_KEYSTRING||""),redirect_uri:etsyRedirectUri(req),code,code_verifier:String(verifier)});
        const tr=await fetch("https://api.etsy.com/v3/public/oauth/token",{method:"POST",headers:{"content-type":"application/x-www-form-urlencoded"},body});
        const tok=await tr.json().catch(()=>({}));
        if(!tr.ok||!tok.access_token)return html(`<h2>Etsy authorization failed.</h2><p>Token exchange returned ${tr.status}.</p>`,500);
        await storeEtsyAuth(env,{access_token:tok.access_token,refresh_token:tok.refresh_token,scope:tok.scope||"",expires_at:Date.now()+(Number(tok.expires_in)||3600)*1000});
        return html('<div style="font-family:Arial;max-width:620px;margin:50px auto"><h1>Etsy shop connected.</h1><p>The Front Shelf can now read paid receipts from your own shop.</p><p><a href="/admin">Return to admin</a></p></div>');
      }

      if(url.pathname==="/api/etsy/order-paid" && req.method==="POST"){
        const rawBody=await req.text();
        const v=await verifyEtsyWebhook(req,env,rawBody);
        if(!v.ok)return json({ok:false,error:v.error},401);

        // Etsy's webhook testing portal sends a signed test event with a fake receipt URL.
        // Accept it after signature verification, but do not try to fulfill the fake order.
        if(req.headers.get("webhook-test")==="true"){
          return json({ok:true,test:true,event:"order.paid"});
        }

        const replayKey=`frontshelf:etsy:webhook:${v.id}`;
        if(await redisPost(env,["GET",replayKey]))return json({ok:true,duplicate:true});
        const p=JSON.parse(rawBody);
        if(p?.event_type!=="order.paid")return json({ok:true,ignored:true});
        if(!p?.resource_url)return json({ok:false,error:"Missing Etsy resource URL."},400);
        const receipt=receiptObject(await fetchEtsyResource(env,p.resource_url));
        const receiptId=String(receipt?.receipt_id||p.resource_url.split("/").filter(Boolean).pop()||"");
        if(!receiptId)return json({ok:false,error:"Could not determine Etsy receipt ID."},500);
        if(receipt?.status&&!["paid","completed"].includes(String(receipt.status).toLowerCase()))return json({ok:true,ignored:true,reason:"receipt-not-paid"});
        if(env.ETSY_PLANNER_LISTING_ID&&!receiptHasPlanner(receipt,env.ETSY_PLANNER_LISTING_ID))return json({ok:true,ignored:true,reason:"not-the-planner-listing"});
        const buyerEmail=receiptBuyerEmail(receipt);
        if(!validEmail(buyerEmail))return json({ok:false,error:"Buyer email was not available on the Etsy receipt."},500);
        await redisPost(env,["SET",`frontshelf:etsy:paid:${receiptId}`,buyerEmail,"EX",String(60*60*24*365*3)]);
        await redisPost(env,["SET",replayKey,"1","EX","604800"]);
        return json({ok:true,verified:true});
      }

      if(url.pathname==="/api/admin/issue" && req.method==="POST"){
        const rl=await rateLimit(env,req,"admin-issue",8,600);
        if(!rl.allowed)return json({ok:false,error:"Too many attempts. Try again later."},429,{"retry-after":"600"});
        const body=await req.json().catch(()=>({}));
        if(typeof body.adminSecret!=="string" || body.adminSecret.length>256 || !env.ADMIN_SECRET || body.adminSecret!==env.ADMIN_SECRET)
          return json({ok:false,error:"Invalid admin secret."},401);
        const email=normEmail(body.email),orderId=cleanOrderId(body.orderId);
        if(!validEmail(email)||!orderId)return json({ok:false,error:"Valid buyer email and Etsy order ID are required."},400);
        const code=await signPayload(env.LICENSE_SIGNING_SECRET,{email,orderId,v:1,issuedAt:Date.now()},"license");
        return json({ok:true,email,orderId,code});
      }

      if(url.pathname==="/api/activate" && req.method==="POST"){
        const rl=await rateLimit(env,req,"activate",20,600);
        if(!rl.allowed)return json({ok:false,error:"Too many activation attempts. Try again later."},429,{"retry-after":"600"});
        const body=await req.json().catch(()=>({}));
        const email=normEmail(body.email),deviceId=cleanDeviceId(body.deviceId),orderId=cleanEtsyReceiptId(body.orderId);
        if(!validEmail(email)||!orderId)return json({ok:false,error:"Enter a valid purchase email and Etsy order number."},400);
        if(!deviceId)return json({ok:false,error:"Invalid device identifier."},400);
        const purchase=await verifyEtsyPurchase(env,email,orderId);
        if(!purchase.ok)return json({ok:false,error:purchase.error},401);
        const key=`frontshelf:devices:${await sha256(email)}`;
        const members=await redis(env,["smembers",key])||[];
        if(!members.includes(deviceId) && members.length>=2)
          return json({ok:false,error:"This license is already active on 2 devices. Use Replace / Reset My Devices."},403);
        await redis(env,["sadd",key,deviceId]);
        await redis(env,["expire",key,String(60*60*24*365*3)]);
        const token=await signPayload(env.LICENSE_SIGNING_SECRET,{email,deviceId,orderId,exp:Date.now()+30*24*60*60*1000},"session");
        return json({ok:true},200,{"set-cookie":sessionCookie(token)});
      }

      if(url.pathname==="/api/sync/get" && req.method==="GET"){
        const session=await verifySession(req,env);
        if(!session)return json({ok:false,error:"Not authorized."},401);
        const key=await syncDataKey(session);
        const stored=await redisPost(env,["GET",key]);
        if(!stored)return json({ok:true,exists:false});
        const cloud=await decryptSyncPayload(env,stored);
        if(!cloud||!cloud.data)return json({ok:true,exists:false});
        return json({ok:true,exists:true,updatedAt:Number(cloud.updatedAt)||0,data:cloud.data});
      }

      if(url.pathname==="/api/sync/save" && req.method==="POST"){
        const session=await verifySession(req,env);
        if(!session)return json({ok:false,error:"Not authorized."},401);
        const body=await req.json().catch(()=>({}));
        const updatedAt=Number(body.updatedAt);
        if(!Number.isFinite(updatedAt)||!body.data||typeof body.data!=="object")
          return json({ok:false,error:"Invalid sync payload."},400);

        const rawSize=new TextEncoder().encode(JSON.stringify(body.data)).byteLength;
        if(rawSize>900000)return json({ok:false,error:"Planner data is too large to sync."},413);

        const key=await syncDataKey(session);
        const existingRaw=await redisPost(env,["GET",key]);
        if(existingRaw){
          const existing=await decryptSyncPayload(env,existingRaw);
          if(existing&&Number(existing.updatedAt)>updatedAt){
            return json({
              ok:false,
              conflict:true,
              cloud:{updatedAt:Number(existing.updatedAt)||0,data:existing.data}
            },409);
          }
        }

        const encrypted=await encryptSyncPayload(env,{updatedAt,data:body.data});
        await redisPost(env,["SET",key,encrypted]);
        await redisPost(env,["EXPIRE",key,String(60*60*24*365*3)]);
        return json({ok:true,updatedAt});
      }

      if(url.pathname==="/api/logout" && req.method==="POST"){
        return new Response(JSON.stringify({ok:true}),{
          status:200,
          headers:{
            "content-type":"application/json; charset=utf-8",
            "set-cookie":"frontshelf_session=; Path=/; HttpOnly; Secure; SameSite=Strict; Max-Age=0",
            "cache-control":"no-store",
            ...BASE_SECURITY_HEADERS
          }
        });
      }

      if(url.pathname==="/api/reset-my-devices" && req.method==="POST"){
        const rl=await rateLimit(env,req,"reset-my-devices",4,3600);
        if(!rl.allowed)return json({ok:false,error:"Too many reset requests. Try again later."},429,{"retry-after":"3600"});
        const session=await verifySession(req,env);
        if(!session)return json({ok:false,error:"Not authorized."},401);
        const emailHash=await sha256(session.email);
        await redisPost(env,["DEL",`frontshelf:devices:${emailHash}`]);
        return new Response(JSON.stringify({ok:true}),{
          status:200,
          headers:{
            "content-type":"application/json; charset=utf-8",
            "set-cookie":"frontshelf_session=; Path=/; HttpOnly; Secure; SameSite=Strict; Max-Age=0",
            "cache-control":"no-store",
            ...BASE_SECURITY_HEADERS
          }
        });
      }

      if(url.pathname==="/api/reset-devices" && req.method==="POST"){
        const rl=await rateLimit(env,req,"reset-devices",6,3600);
        if(!rl.allowed)return json({ok:false,error:"Too many reset attempts. Try again later."},429,{"retry-after":"3600"});
        const body=await req.json().catch(()=>({}));
        const email=normEmail(body.email),deviceId=cleanDeviceId(body.deviceId),orderId=cleanEtsyReceiptId(body.orderId);
        if(!validEmail(email)||!orderId)return json({ok:false,error:"Enter a valid purchase email and Etsy order number."},400);
        if(!deviceId)return json({ok:false,error:"Invalid device identifier."},400);
        const purchase=await verifyEtsyPurchase(env,email,orderId);
        if(!purchase.ok)return json({ok:false,error:purchase.error},401);

        // Purchase-only resets are allowed only when there are currently no active devices.
        // If devices already exist, the buyer must reset from an authenticated device in Account & Devices.
        const key=`frontshelf:devices:${await sha256(email)}`;
        const members=await redis(env,["smembers",key])||[];
        if(members.length>0)
          return json({ok:false,error:"For security, reset active devices from Account & Devices on a currently authorized device."},403);

        await redis(env,["sadd",key,deviceId]);
        await redis(env,["expire",key,String(60*60*24*365*3)]);
        const token=await signPayload(env.LICENSE_SIGNING_SECRET,{email,deviceId,orderId,exp:Date.now()+30*24*60*60*1000},"session");
        return json({ok:true},200,{"set-cookie":sessionCookie(token)});
      }

      return new Response("Not found",{status:404});
    } catch(err) {
      console.error(err);
      return json({ok:false,error:"The Front Shelf access service is temporarily unavailable."},500);
    }
  }
};
